  '系统操作依赖专业技能、物理交互限制效率、需求响应总是滞后——交互方式没跟上，AI 能力就落不了地。':
    'システム操作は専門スキルに依存し、物理的インタラクションは効率を制限し、ニーズへの応答は常に遅れがち——インタラクション方式が追いつかなければ、AI の能力は実装できません。',
  现场状态黑箱: '現場状態のブラックボックス',
  '现场状态是黑箱、运维半径受限、非标设备接入处处是坑——想看见远端，却被距离和成本挡住。':
    '現場状態はブラックボックス、運用保守範囲は制限され、非標準デバイスの接続は落とし穴だらけ——遠隔地を見たいのに、距離とコストに阻まれます。',
  '消灭现场盲区，打破距离成本：构建从城市到野外的全域感知网络。':
    '現場の死角をなくし、距離とコストの壁を打破する：都市から野外までの全域センシングネットワークを構築します。',
  '写创客日志、录 30 秒演示视频、用 2 分钟把「痛点 → 方案 → 演示 → 价值」讲给陌生人听。':
    'メイカージャーナルを書き、30秒のデモ動画を撮り、2分で「痛点 → 解決策 → デモ → 価値」を見知らぬ人に伝える。',
  形成业务闭环: 'ビジネス完結ループを形成する',
  '需求响应滞后，被动服务': 'ニーズ応答の遅延、受動的サービス',
  '选课后排（16×1h）前请注意：16 × 1h = 16 小时，比周课排的 20 小时少 4 小时；每节固定开销（开机、发设备、连线、收纳）约 10 分钟，节数越多损耗越大——实际动手时间约 13h vs 18h。取舍是真实的：FP 迭代从两轮压到一轮，发布会 1 小时偏紧，建议争取双节连堂。':
    '放課後スケジュール（16×1時間）を選ぶ前の注意点：16 × 1時間 = 16時間、週間スケジュールの20時間より4時間少ない；各回の固定オーバーヘッド（起動、デバイス配布、接続、片付け）は約10分、回数が多いほどロスが大きい——実作業時間は約13時間 vs 18時間。トレードオフは現実的です：FP の反復は2ラウンドから1ラウンドに圧縮、デモデイは1時間では厳しいため、2コマ連続を確保することを推奨します。',
  学生不会写代码: '学生はコードを書けない',
  '学生不会写代码、合格师资极少、从创意到原型总是断层——硬件启蒙卡在"先学会编程"这道伪门槛上。M0 把门槛拆掉，让想象力重新成为真正的难题。':
    '学生はコードを書けず、適格な指導者は極めて少なく、アイデアからプロトタイプへは常に断絶がある——ハードウェア入門は「まずプログラミングを学べ」という偽のハードルに阻まれています。M0 はそのハードルを取り除き、想像力こそが真の課題となるようにします。',
  '学生自己想解决的问题，不是老师布置的题目。硬件回收，作品照片／视频保留。':
    '学生自身が解決したい問題であり、教師が与えた課題ではありません。ハードウェアは回収、作品の写真／動画は保存。',
