  // M1-M6 curriculum translations
  '基于Home Assistant与ESPHome，在局域网内统一接入多协议设备，实现能耗监控与自动化联动。':
    'Home AssistantとESPHomeをベースに、ローカルネットワーク内でマルチプロトコルデバイスを統一的に接続し、エネルギー消費モニタリングと自動連携を実現します。',
  '商业楼宇、老旧设施、酒店公寓与工厂辅助车间中，空调、照明、安防等多套子系统独立运行，运维人员需多平台切换且数据互不相通。缺乏回路级能耗计量，仅能查看总表账单，无法精确定位高耗能设备与浪费时段。传统BA系统采用专有封闭协议，设备扩展与更换依赖原厂，改造成本高且周期长。':
    '商業ビル、老朽化施設、ホテル・アパート、工場の補助作業場などでは、空調、照明、セキュリティなど複数のサブシステムが独立して動作し、運用保守担当者は複数プラットフォームを切り替える必要があり、データも相互に連携していません。回路レベルのエネルギー消費計測が不足しており、全体の請求書しか確認できず、高消費電力機器や無駄な時間帯を正確に特定できません。従来のBAシステムは専有の閉鎖プロトコルを採用しており、デバイスの拡張や交換はメーカー依存となり、改造コストが高く期間も長くなります。',
  '入门 / 进阶 / 高级': '初級 / 中級 / 上級',
  'L1 1天 / L2 2–3天 / L3 3–5天': 'L1 1日 / L2 2〜3日 / L3 3〜5日',
  'L1无需编程基础，会基本电脑操作与本地区域网连接即可；L2需有基础编程概念，能读懂YAML配置文件；L3需有YAML/Node-RED与网络基础，熟悉L1–L2能力':
    'L1はプログラミング基礎不要で、基本的なPC操作とローカルネットワーク接続ができれば受講可能です；L2は基礎的なプログラミング概念が必要で、YAML設定ファイルが読めることが求められます；L3はYAML/Node-REDとネットワーク基礎が必要で、L1〜L2の能力に習熟していることが求められます。',
