  '基于物理AI终端，融合边缘视觉、语音与业务系统API，实现多模态空间交互。':
    '物理AI端末をベースに、エッジビジョン、音声、業務システムAPIを融合し、マルチモーダル空間インタラクションを実現します。',
  '仓储管理、展厅导览、智能前台等场景中，现场人员需停下手工操作，通过键盘或手机手动检索业务数据，效率低下。传统交互终端缺乏视觉上下文，无法主动感知人员靠近或异常动作。智能终端多为封闭生态，难以与存量WMS/ERP/CRM系统对接；部分工业与政企场景禁止音频与业务数据上传公网。':
    '倉庫管理、展示場ガイド、スマート受付などのシーンでは、現場担当者は手作業を中断し、キーボードやスマートフォンで業務データを手動検索する必要があり、効率が低下します。従来のインタラクション端末はビジョンコンテキストに欠け、人員の接近や異常動作を能動的に感知できません。スマート端末の多くは閉鎖エコシステムであり、既存のWMS/ERP/CRMシステムとの連携が困難です；一部の産業・官公庁シーンでは音声と業務データの公衆網へのアップロードが禁止されています。',
  'L1零基础或首次接触边缘AI交互设备；L2需具备Docker基础与REST API调用经验；L3需具备Linux、PyTorch/Jetson基础与shell操作能力':
    'L1は基礎ゼロまたはエッジAIインタラクションデバイス初接触者向け；L2はDocker基礎とREST API呼び出し経験が必要；L3はLinux、PyTorch/Jetson基礎とshell操作能力が必要です。',
