  '基于 LoRa Mesh 自组网协议，构建无公网依赖、多跳中继的离网应急通信与传感数据回传网络。':
    'LoRa Mesh 自己組織化ネットワークプロトコルをベースに、公衆網に依存しないマルチホップ中継によるオフグリッド緊急通信とセンシングデータバックホールネットワークを構築します。',
  '野外勘探、隧道施工、应急搜救等场景缺乏蜂窝基站覆盖，传统对讲机视距受限且无法回传坐标与传感数据。单点中继台依赖市电与高位节点，一旦受损整网中断；卫星电话终端昂贵且存在遮挡盲区，临时专网架设周期长、成本高。':
    '野外探査、トンネル工事、緊急救助などのシーンではセルラー基地局のカバレッジが不足しており、従来のトランシーバーは見通し距離に制限され、座標やセンシングデータをバックホールできません。単点中継局は商用電源と高所ノードに依存しており、一度損傷するとネットワーク全体が中断します；衛星電話端末は高額で遮蔽による不感地帯が存在し、臨時プライベートネットワークの構築は期間が長くコストも高くなります。',
  '入门至高级（分 L1/L2/L3 三级）': '初級から上級（L1/L2/L3 の3レベル）',
