  'L1 会使用智能手机与蓝牙配对，了解基础物联网概念；L2 具备 Node-RED 或 MQTT 基础，能配置网络与 Broker；L3 熟悉 C/C++ 与 PlatformIO，能阅读并修改开源固件源码':
    'L1はスマートフォンの使用とBluetoothペアリングができ、基礎的なIoT概念を理解していること；L2はNode-REDまたはMQTT基礎があり、ネットワークとBrokerの設定ができること；L3はC/C++とPlatformIOに習熟し、オープンソースファームウェアソースコードの読解と修正ができること。',
