    '軽量エッジカメラと産業グレードマルチチャンネルAIコンピューティングホストをベースに、物体検出、エリア侵入アラート、自動連携を備えたエッジビジョンソリューションを構築します。',
  '传统监控仅能事后录像回溯，无法在风险发生瞬间产生结构化告警；移动侦测受光线变化、雨雪晃动干扰严重，误报率高。视觉 AI 定制开发周期长、需专门算法工程师与专用服务机架，方案商难以权衡单点嵌入式设备与多路集中服务器的性能与成本。':
    '従来の監視カメラは事後の録画再生しかできず、リスク発生瞬間に構造化されたアラートを生成できません；動体検知は光線変化や雨雪の揺れによる干渉が深刻で、誤報率が高くなります。ビジョンAIのカスタム開発は期間が長く、専門のアルゴリズムエンジニアと専用サーバーラックが必要となり、ソリューションプロバイダーは単点組み込みデバイスとマルチチャンネル集中サーバーの性能とコストのトレードオフを判断するのが困難です。',
  'L1 具备基础网络与浏览器操作经验，能连接 Wi-Fi 与访问 Web 界面；L2 理解 IP 网络、Docker 与 MQTT 基础，能编辑 YAML 配置文件；L3 具备 Python 与 Linux 命令行基础，了解目标检测基本原理':
    'L1は基礎的なネットワークとブラウザ操作経験があり、Wi-Fi接続とWebインターフェースアクセスができること；L2はIPネットワーク、Docker、MQTT基礎を理解し、YAML設定ファイルの編集ができること；L3はPythonとLinuxコマンドライン基礎があり、物体検出の基本原理を理解していること。',
