    'TensorRTと組み込みモデル量子化変換のキーツールチェーンを習得する',
  具备独立设计和交付垂直行业视觉识别方案的能力:
    '垂直産業向けビジョン認識ソリューションを独立して設計・納品する能力を備える',
  '交付 1 套自定义训练的目标检测模型，并在硬件上完成实跑验证':
    'カスタムトレーニングした物体検出モデルを1セット納品し、ハードウェア上での実行検証を完了する',
  '工业级传感器与4G/LoRaWAN双链路，实现广域场景低功耗环境监测与数据采集。':
    '産業グレードセンサーと4G/LoRaWANデュアルリンクにより、広域シーンでの低消費電力環境モニタリングとデータ収集を実現します。',
  '面向连栋温室大棚、设施园艺、河道水质监测、城市内涝点与工业仓储等广域分散场景，偏远点位布线取电成本高，野外山地与河流断面上百米至数公里铺设线缆工程量巨大。现场多厂商传感器各自定义私有协议，二次开发与协议适配周期长；霜冻、水质恶化、土壤干旱等异常依赖人工定期巡检，故障发现晚且耗费人力；采集到的环境数据停留在云端大屏或手机App，无法与既有灌溉/风机等执行机构联动，也无法对接第三方业务系统。':
    '連棟ビニールハウス、施設園芸、河川水質モニタリング、都市内水氾濫ポイント、産業倉庫などの広域分散シーンでは、僻地ポイントの配線・給電コストが高く、野外の山地や河川断面での数百メートルから数キロメートルにわたるケーブル敷設は工事量が膨大です。現場では複数メーカーのセンサーが各々独自プロトコルを定義しており、二次開発とプロトコル適合の期間が長くなります；霜害、水質悪化、土壌乾燥などの異常は人手による定期巡回点検に依存しており、故障発見が遅れ人的コストもかさみます；収集された環境データはクラウドの大画面やスマホアプリに留まり、既存の灌漑/ファンなどのアクチュエーターと連携できず、サードパーティ業務システムとの連携もできません。',
  'L1无；L2建议具备RS485/Modbus或电子接线基础，能读懂传感器接线图；L3建议具备HTTP API调用、JSON解析与Linux命令行基础':
    'L1は特になし；L2はRS485/Modbusまたは電子配線基礎があり、センサー配線図が読めることが推奨されます；L3はHTTP API呼び出し、JSON解析、Linuxコマンドライン基礎があることが推奨されます。',
  '智慧农业与设施园艺：土壤温湿度/EC监测、温室CO2浓度调控、精准水肥灌溉联动':
    'スマート農業と施設園芸：土壌温湿度/ECモニタリング、ハウスCO2濃度制御、精密水肥灌漑連携',
