    'LeRobotテレオペレーション動作データセット収集 → VLA身体化大規模モデルとIsaac Simシミュレーション初歩探究',
  'M6 不是一门教学生「调机械臂参数」的课，而是一门教团队如何用开源工具链和轻量硬件，把视觉感知、自然语言指令与物理执行机构打通的方法课。柴火交付的从来不只是「一次上课」，而是一整套可以被拆开、改写、重新组装的东西：15模块课程骨架、教师教案与PPT、SenseCraft动作配置模板、Python抓取工程源码、Pinocchio/Motorbridge调用示例、LeRobot数据集采集规范、设备清单与台架安全规范。':
    'M6は学生に「ロボットアームのパラメータ調整」を教える講座ではなく、チームにオープンソースツールチェーンと軽量ハードウェアを用いてビジョンセンシング、自然言語コマンド、物理アクチュエーターを連携させる方法を教える講座です。柴火が提供するのは決して「一度の授業」だけではなく、分解し、書き換え、再構築できる一式です：15モジュールの講座骨格、教師用教案とPPT、SenseCraftアクション設定テンプレート、Pythonグラスピングプロジェクトソースコード、Pinocchio/Motorbridge呼び出しサンプル、LeRobotデータセット収集規範、デバイス一覧とラック安全規範。',
