  'Python调用Motorbridge SDK驱动平滑运动与夹爪控制、整合全流程：深度相机检测→Pinocchio逆解→Motorbridge驱动抓取':
    'PythonでMotorbridge SDKを呼び出して平滑な運動とグリッパー制御を駆動し、全フローを統合：深度カメラ検出→Pinocchio逆運動学ソルバー→Motorbridge駆動グラスピング',
  'Python调用Pinocchio工具库、输入目标坐标自动计算6关节角度、超出工作范围/解算失败异常报警与安全退回':
    'PythonでPinocchioツールライブラリを呼び出し、目標座標を入力して6関節角度を自動計算、作業範囲超過/ソルバー失敗の異常アラームと安全退避',
  'RGB-D深度相机 · 3D空间坐标定位': 'RGB-D深度カメラ · 3D空間座標測位',
  'SenseCraft 3D预览': 'SenseCraft 3Dプレビュー',
  SenseCraft开箱与主从遥操: 'SenseCraft開箱とマスタースレーブテレオペレーション',
  'SenseCraft开箱与主从遥操 → 语音指令夹取首验 → 总结复盘':
    'SenseCraft開箱とマスタースレーブテレオペレーション → 音声コマンドグラスピング初体験 → 総括レビュー',
  'SenseCraft解决「看得见、能演示」的展示层需求，让学员第一天就能跑通主从遥操与语音夹取；Python + Pinocchio + Motorbridge让系统第一次具备确定性3D空间抓取的工程能力，从「演示可用」走向「可交付工程」。':
    'SenseCraftは「見える、デモできる」デモレベルのニーズを解決し、受講生が初日からマスタースレーブテレオペレーションと音声グラスピングを動作確認できるようにします；Python + Pinocchio + Motorbridgeにより、システムが初めて決定論的3D空間グラスピングのエンジニアリング能力を備え、「デモ可能」から「納品可能なエンジニアリング」へと進化します。',
