  'L1/L2 云端协同方案要求现场具备稳定上行互联网带宽，用于 SenseCraft AI 平台与大模型服务调用；无外网环境下 L1/L2 无法运行，需切换至 L3 离线方案。':
    'L1/L2クラウド連携ソリューションは、現場に安定した上りインターネット帯域幅が必要で、SenseCraft AIプラットフォームと大規模モデルサービス呼び出しに使用されます；外部ネットワーク環境がない場合、L1/L2は実行できず、L3オフラインソリューションに切り替える必要があります。',
  'L1/L2业务数据经本地MCP桥接在局域网内流转，核心数据不出域；L3纯本地离线运行，零公网依赖。':
    'L1/L2の業務データはローカルMCPブリッジを経由してローカルネットワーク内で流转し、コアデータはドメイン外に出ません；L3は純ローカルオフラインで実行され、公衆網依存はゼロです。',
  'L1/L2依赖互联网连接大模型服务；L3需100 TOPS级别边缘算力（Jetson Orin NX 16GB），RK3588-40（6 TOPS）无法承载本地大模型推理。':
    'L1/L2はインターネット接続による大規模モデルサービスに依存します；L3は100 TOPSクラスのエッジコンピューティング（Jetson Orin NX 16GB）が必要で、RK3588-40（6 TOPS）ではローカル大規模モデル推論を実行できません。',
  'L1/L2方案依赖互联网连接大模型服务，无外网环境须切换至L3离线方案':
    'L1/L2ソリューションはインターネット接続による大規模モデルサービスに依存し、外部ネットワーク環境がない場合はL3オフラインソリューションに切り替える必要があります',
  'L3 纯本地方案依赖 100 TOPS 级别边缘 GPU 硬件（Jetson Orin NX 16GB 及以上），6 TOPS 的 RK3588-40 无法承载本地大模型推理。':
    'L3純ローカルソリューションは100 TOPSクラスのエッジGPUハードウェア（Jetson Orin NX 16GB以上）に依存し、6 TOPSのRK3588-40ではローカル大規模モデル推論を実行できません。',
  'L3离线方案需100 TOPS级别边缘算力（Jetson Orin NX 16GB及以上），RK3588-40（6 TOPS）无法承载本地大模型推理':
    'L3オフラインソリューションには100 TOPSクラスのエッジコンピューティング（Jetson Orin NX 16GB以上）が必要で、RK3588-40（6 TOPS）ではローカル大規模モデル推論を実行できません',
