  'LoRa射频参数调优（扩频因子SF、带宽BW、发射功率）、视距与非视距传输距离测试、障碍物衰减评估':
    'LoRa無線パラメータチューニング（拡散係数SF、帯域幅BW、送信電力）、見通し内・見通し外伝送距離テスト、障害物減衰評価',
  'LoRa频段必须符合部署所在国家/地区的无线电管理规定（中国CN470-510、欧盟EU868、美国US915），严禁擅自使用未授权频段或超出法定发射功率':
    'LoRa周波数帯はデプロイ先の国/地域の電波管理規定（中国CN470-510、EU EU868、米国US915）に適合しなければならず、未承認周波数帯の使用や法定送信電力を超えることを厳禁します',
  'LoRa频段必须符合部署所在国家/地区的无线电管理规定（中国CN470-510、欧盟EU868、美国US915），严禁擅自使用未授权频段或超出法定发射功率。户外测试需提前确认场地无线电环境，避免对其他合法无线电业务造成干扰。':
    'LoRa周波数帯はデプロイ先の国/地域の電波管理規定（中国CN470-510、EU EU868、米国US915）に適合しなければならず、未承認周波数帯の使用や法定送信電力を超えることを厳禁します。屋外テストでは事前にフィールドの電波環境を確認し、他の合法的な無線業務への干渉を回避してください。',
  'M1 不是一门教学生「玩智能家居」的课，而是一门教团队如何用开源平台和轻量硬件，把现场已经存在的、互相割裂的设备统一接进来的方法课。柴火交付的从来不只是「一次上课」，而是一整套可以被拆开、改写、重新组装的东西：13模块课程骨架、教师教案与PPT、ESPHome示例配置、YAML模板、Modbus寄存器映射工具、设备清单与台架规范。':
    'M1は学生に「スマートホームで遊ぶ」ことを教える講座ではなく、チームにオープンソースプラットフォームと軽量ハードウェアを用いて、現場に既に存在し互いに分断されたデバイスを統一的に接続する方法を教える講座です。柴火が提供するのは決して「一度の授業」だけではなく、分解し、書き換え、再構築できる一式です：13モジュールの講座骨格、教師用教案とPPT、ESPHomeサンプル設定、YAMLテンプレート、Modbusレジスタマッピングツール、デバイス一覧とラック規範。',
  'M2 不是一门教学生「跟AI聊天」的课，而是一门教团队如何用物理AI终端和标准协议，把现场已经存在的WMS/ERP/CRM系统接进自然语言交互的方法课。柴火交付的从来不只是「一次上课」，而是一整套可以被拆开、改写、重新组装的东西：15模块课程骨架、教师教案与PPT、Watcher配置模板、MCP桥接config.yml示例、Docker Compose部署文件、离线语音管线部署手册。':
    'M2は学生に「AIとチャットする」ことを教える講座ではなく、チームに物理AI端末と標準プロトコルを用いて、現場に既に存在するWMS/ERP/CRMシステムを自然言語インタラクションに接続する方法を教える講座です。柴火が提供するのは決して「一度の授業」だけではなく、分解し、書き換え、再構築できる一式です：15モジュールの講座骨格、教師用教案とPPT、Watcher設定テンプレート、MCPブリッジconfig.ymlサンプル、Docker Composeデプロイファイル、オフライン音声パイプラインデプロイマニュアル。',
  'M3 不是一门教学生「玩无线电」的课，而是一门教团队如何用低功耗广域网技术，把公网覆盖不到的户外区域的传感器数据收回来的方法课。柴火交付的从来不只是「一次上课」，而是一整套可以被拆开、改写、重新组装的东西：12模块课程骨架、教师教案与PPT、LoRaWAN节点配置模板、ChirpStack部署指南、Meshtastic频道配置示例、户外测试场地评估清单。':
    'M3は学生に「無線で遊ぶ」ことを教える講座ではなく、チームに低消費電力広域ネットワーク技術を用いて、公衆網カバレッジのない屋外エリアのセンサーデータを収集する方法を教える講座です。柴火が提供するのは決して「一度の授業」だけではなく、分解し、書き換え、再構築できる一式です：12モジュールの講座骨格、教師用教案とPPT、LoRaWANノード設定テンプレート、ChirpStackデプロイガイド、Meshtasticチャンネル設定サンプル、屋外テストフィールド評価チェックリスト。',
  'M4 不是一门教学生「装监控」的课，而是一门教团队如何用计算机视觉和边缘推理，让摄像头从录像设备变成智能感知节点的方法课。柴火交付的从来不只是「一次上课」，而是一整套可以被拆开、改写、重新组装的东西：12模块课程骨架、教师教案与PPT、Frigate配置模板、YOLO推理示例代码、自定义数据集标注规范、摄像头选型与部署清单。':
    'M4は学生に「監視カメラを設置する」ことを教える講座ではなく、チームにコンピュータービジョンとエッジ推論を用いて、カメラを録画デバイスからスマートセンシングノードに変える方法を教える講座です。柴火が提供するのは決して「一度の授業」だけではなく、分解し、書き換え、再構築できる一式です：12モジュールの講座骨格、教師用教案とPPT、Frigate設定テンプレート、YOLO推論サンプルコード、カスタムデータセットアノテーション規範、カメラ選定とデプロイチェックリスト。',
  'M5 不是一门教学生「写PLC程序」的课，而是一门教团队如何用工业控制和边缘计算，把零散设备串成一条可观测、可控制的自动化产线的方法课。柴火交付的从来不只是「一次上课」，而是一整套可以被拆开、改写、重新组装的东西：12模块课程骨架、教师教案与PPT、PLC编程示例工程、OPC UA配置模板、Grafana仪表盘配置、数字孪生模型示例。':
    'M5は学生に「PLCプログラムを書く」ことを教える講座ではなく、チームに産業用制御とエッジコンピューティングを用いて、散在するデバイスを観測可能で制御可能な自動化生産ラインとして連携させる方法を教える講座です。柴火が提供するのは決して「一度の授業」だけではなく、分解し、書き換え、再構築できる一式です：12モジュールの講座骨格、教師用教案とPPT、PLCプログラミングサンプルプロジェクト、OPC UA設定テンプレート、Grafanaダッシュボード設定、デジタルツインモデルサンプル。',
