  'XIAO ESP32 + ESPHome传感器节点': 'XIAO ESP32 + ESPHomeセンサーノード',
  'XIAO RS485扩展板读取XY-MD02温湿度变送器，接入DDSU666电表读取电压/电流/功率/累计电量':
    'XIAO RS485拡張ボードでXY-MD02温湿度トランスミッターを読み取り、DDSU666電力量計に接続して電圧/電流/電力/積算電力量を読み取る',
