  'XIAO传感器节点 → 能耗看板初识 → 总结复盘':
    'XIAOセンサーノード → エネルギーダッシュボード入門 → 総括レビュー',
  'XY-MD02 温湿度变送器': 'XY-MD02 温湿度トランスミッター',
  'YOLOv8/YOLOv11目标检测模型部署、置信度与NMS阈值调优、自定义数据集标注与微调（Roboflow/LabelImg）、推理性能优化（TensorRT/ONNX）':
    'YOLOv8/YOLOv11物体検出モデルデプロイ、信頼度とNMSしきい値チューニング、カスタムデータセットアノテーションとファインチューニング（Roboflow/LabelImg）、推論性能最適化（TensorRT/ONNX）',
  'coverage 键对应排课形态 ID（taster / workshop / bootcamp），值为 full（完整覆盖）/ part（精简覆盖）/ none（不含）/ plus（比完整版更深）。体验课（taster）聚焦 L1 PLC控制与数据采集演示，不含产线级调度与数字孪生；实战课（workshop）覆盖 L1+L2 完整PLC编程、数据采集与可视化；交付课（bootcamp）全覆盖 L1+L2+L3，含多工位协同与数字孪生预测性维护。':
    'coverageキーは授業形態ID（taster / workshop / bootcamp）に対応し、値はfull（完全網羅）/ part（簡易網羅）/ none（含まず）/ plus（フルバージョンより深い）です。体験講座（taster）はL1のPLC制御とデータ収集デモに焦点を当て、生産ラインレベルスケジューリングとデジタルツインは含みません；実践講座（workshop）はL1+L2の完全なPLCプログラミング、データ収集、可視化をカバーします；納品講座（bootcamp）はL1+L2+L3を完全網羅し、マルチステーション協調とデジタルツイン予知保全を含みます。',
  'coverage 键对应排课形态 ID（taster / workshop / bootcamp），值为 full（完整覆盖）/ part（精简覆盖）/ none（不含）/ plus（比完整版更深）。体验课（taster）聚焦 L1 平台接入与传感器节点，不含工业总线与业务集成；实战课（workshop）覆盖 L1+L2 完整工业总线与能耗看板；交付课（bootcamp）全覆盖 L1+L2+L3。':
    'coverageキーは授業形態ID（taster / workshop / bootcamp）に対応し、値はfull（完全網羅）/ part（簡易網羅）/ none（含まず）/ plus（フルバージョンより深い）です。体験講座（taster）はL1のプラットフォーム接続とセンサーノードに焦点を当て、産業用バスとビジネス統合は含みません；実践講座（workshop）はL1+L2の完全な産業用バスとエネルギーダッシュボードをカバーします；納品講座（bootcamp）はL1+L2+L3を完全網羅します。',
  'coverage 键对应排课形态 ID（taster / workshop / bootcamp），值为 full（完整覆盖）/ part（精简覆盖）/ none（不含）/ plus（比完整版更深）。体验课（taster）聚焦 L1 户外LoRa通信与Meshtastic自组网体验，不含LoRaWAN网关部署与远程运维；实战课（workshop）覆盖 L1+L2 完整LoRaWAN组网与数据集成；交付课（bootcamp）全覆盖 L1+L2+L3，含远程运维与大规模部署管理。':
    'coverageキーは授業形態ID（taster / workshop / bootcamp）に対応し、値はfull（完全網羅）/ part（簡易網羅）/ none（含まず）/ plus（フルバージョンより深い）です。体験講座（taster）はL1の屋外LoRa通信とMeshtastic自律分散型ネットワーク体験に焦点を当て、LoRaWANゲートウェイデプロイとリモート運用保守は含みません；実践講座（workshop）はL1+L2の完全なLoRaWANネットワーキングとデータ統合をカバーします；納品講座（bootcamp）はL1+L2+L3を完全網羅し、リモート運用保守と大規模デプロイ管理を含みます。',
  'coverage 键对应排课形态 ID（taster / workshop / bootcamp），值为 full（完整覆盖）/ part（精简覆盖）/ none（不含）/ plus（比完整版更深）。体验课（taster）聚焦 L1 摄像头接入与基础视觉推理演示，不含多摄像头协同与边缘隐私部署；实战课（workshop）覆盖 L1+L2 完整Frigate NVR部署与告警联动；交付课（bootcamp）全覆盖 L1+L2+L3，含多摄像头协同与纯边缘隐私部署。':
    'coverageキーは授業形態ID（taster / workshop / bootcamp）に対応し、値はfull（完全網羅）/ part（簡易網羅）/ none（含まず）/ plus（フルバージョンより深い）です。体験講座（taster）はL1のカメラ接続と基本ビジョン推論デモに焦点を当て、マルチカメラ協調とエッジプライバシーデプロイは含みません；実践講座（workshop）はL1+L2の完全なFrigate NVRデプロイとアラート連携をカバーします；納品講座（bootcamp）はL1+L2+L3を完全網羅し、マルチカメラ協調と純エッジプライバシーデプロイを含みます。',
  'coverage 键对应排课形态 ID（taster / workshop / bootcamp），值为 full（完整覆盖）/ part（精简覆盖）/ none（不含）/ plus（比完整版更深）。体验课（taster）聚焦 L1 端侧体验与MCP工具调用演示，不含本地业务系统部署与离线管线；实战课（workshop）覆盖 L1+L2 完整Watcher配置、WMS部署与MCP桥接；交付课（bootcamp）全覆盖 L1+L2+L3，含Jetson离线语音管线部署。':
    'coverageキーは授業形態ID（taster / workshop / bootcamp）に対応し、値はfull（完全網羅）/ part（簡易網羅）/ none（含まず）/ plus（フルバージョンより深い）です。体験講座（taster）はL1のエッジ側体験とMCPツール呼び出しデモに焦点を当て、ローカル業務システムデプロイとオフラインパイプラインは含みません；実践講座（workshop）はL1+L2の完全なWatcher設定、WMSデプロイ、MCPブリッジをカバーします；納品講座（bootcamp）はL1+L2+L3を完全網羅し、Jetsonオフライン音声パイプラインデプロイを含みます。',
  '—— 冯磊，本系列课程作者': '—— 馮磊、本シリーズ講座著者',
