  '检测准确率受光照条件、摄像头角度、遮挡情况与目标距离影响，不承诺特定场景下的具体准确率指标':
    '検出精度は光照条件、カメラ角度、遮蔽状況、ターゲット距離に影響され、特定シーンにおける具体的な精度指標を保証しません',
  '模块 01–11': 'モジュール 01–11',
  '模块 03「户外LoRa通信」的测试场景是开放的：你的行业、你的客户现场、这座城市正在发生的一个真问题。测距离可以是园区，可以是农田，可以是山区——场景越靠近真实现场，效果越好，而这件事你比我们懂。':
    'モジュール03「屋外LoRa通信」のテストシーンはオープンです：あなたの業界、あなたの顧客現場、この街で今起きている本当の問題。距離測定は工業団地でも、農地でも、山岳地帯でも構いません——シーンが現実の現場に近いほど効果は高まり、そのことはあなたが私たちよりよく知っています。',
  '模块 04 + 05 + 13(精简)': 'モジュール 04 + 05 + 13(簡易版)',
  '模块 04「产线数据可视化」的监控指标是开放的：你的行业、你的客户现场、这座城市正在发生的一个真问题。算OEE可以是组装线，可以是包装线，可以是检测线——指标越靠近真实现场，效果越好，而这件事你比我们懂。':
    'モジュール04「生産ラインデータ可視化」の監視指標はオープンです：あなたの業界、あなたの顧客現場、この街で今起きている本当の問題。OEE計算は組立ラインでも、包装ラインでも、検査ラインでも構いません——指標が現実の現場に近いほど効果は高まり、そのことはあなたが私たちよりよく知っています。',
  '模块 04「场景化语音问答」的查询内容是开放的：你的行业、你的客户现场、这座城市正在发生的一个真问题。查库存可以是仓管，可以是展厅展品，可以是会议室日程——问题越靠近真实现场，效果越好，而这件事你比我们懂。':
    'モジュール04「シーン別音声Q&A」の照会内容はオープンです：あなたの業界、あなたの顧客現場、この街で今起きている本当の問題。在庫照会は倉庫管理でも、展示場の展示品でも、会議室のスケジュールでも構いません——問題が現実の現場に近いほど効果は高まり、そのことはあなたが私たちよりよく知っています。',
  '模块 04「智能告警联动」的检测场景是开放的：你的行业、你的客户现场、这座城市正在发生的一个真问题。测异常可以是仓库闯入，可以是车间离岗，可以是停车场违停——场景越靠近真实现场，效果越好，而这件事你比我们懂。':
    'モジュール04「スマートアラート連携」の検出シーンはオープンです：あなたの業界、あなたの顧客現場、この街で今起きている本当の問題。異常検出は倉庫侵入でも、工場での離席でも、駐車場での違法駐車でも構いません——シーンが現実の現場に近いほど効果は高まり、そのことはあなたが私たちよりよく知っています。',
  '模块 09「场景自动化策略配置」的联动规则是开放的：你的行业、你的客户现场、这座城市正在发生的一个真问题。温度超限可以是机房，可以是冷库，可以是养殖大棚——问题越靠近真实现场，效果越好，而这件事你比我们懂。':
    'モジュール09「シーン自動化ポリシー設定」の連携ルールはオープンです：あなたの業界、あなたの顧客現場、この街で今起きている本当の問題。温度超過はサーバールームでも、冷蔵倉庫でも、養殖ハウスでも構いません——問題が現実の現場に近いほど効果は高まり、そのことはあなたが私たちよりよく知っています。',
