    '環境事前チェック → ビジョンAIコアコンセプト → reCamera単点軽量ノード設定',
  '环境预检 → 视觉概念 → reCamera配置 → 基础检测 → Jetson NVR演示':
    '環境事前チェック → ビジョンコンセプト → reCamera設定 → 基本検出 → Jetson NVRデモ',
  '现场数据采集策略（光照变化/角度多源/正负样本平衡）、CVAT或Roboflow目标检测框标注、数据集划分7:2:1与数据增强':
    '現場データ収集戦略（光照変化/角度マルチソース/正負サンプルバランス）、CVATまたはRoboflow物体検出ボックスアノテーション、データセット分割7:2:1とデータ拡張',
  '目标检测、区域入侵告警与自动化联动': '物体検出、エリア侵入アラートと自動化連携',
  '目标检测统计数据写入InfluxDB时序数据库、Grafana告警频次统计/区域热度/合规率趋势看板搭建':
    '物体検出統計データをInfluxDB時系列データベースに書き込み、Grafanaアラート頻度統計/エリアヒートマップ/コンプライアンス率トレンドダッシュボードを構築',
  '硬件台架清点、网络环境配置、reCamera固件预置与Node-RED/SSCMA插件验证、Frigate容器部署与GPU直通配置、教学资料下发':
    'ハードウェアラックの清点、ネットワーク環境設定、reCameraファームウェアプリセットとNode-RED/SSCMAプラグイン検証、FrigateコンテナデプロイとGPUパススルー設定、教材の配布',
