    '軽量エッジノード · エッジ側NPU推論 · RTSPストリーミング',
  边缘端实跑: 'エッジ側実機実行',
  边缘端模型转换与部署: 'エッジ側モデル変換とデプロイ',
  '边缘端模型转换与部署 → 结构化数据汇聚与看板搭建':
    'エッジ側モデル変換とデプロイ → 構造化データ集約とダッシュボード構築',
  '这门课的价值不在算法精度，在「把视觉AI从演示台架搬到客户现场」的工程方法':
    'この講座の価値はアルゴリズム精度にあるのではなく、「ビジョンAIをデモラックから顧客現場に移す」エンジニアリング方法にあります',
  '通用与特定目标检测（人/车/安全帽/反光衣/工件等物体类别）':
    '汎用および特定ターゲット検出（人/車/ヘルメット/反射材/ワークピースなどの物体カテゴリ）',
  '高性能开源 AI 视觉相机，进阶视觉开发与更高算力模型验证':
    '高性能オープンソースAIビジョンカメラ、応用ビジョン開発とより高いコンピューティング性能のモデル検証',
  '1 天 · 6–8h · L1 展示层 · 聚焦双通信架构认知与云端数据监视':
    '1日 · 6〜8時間 · L1 デモレベル · デュアル通信アーキテクチャ認識とクラウドデータ監視に焦点',
